import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;

public class ColorMasterTest {
    public static void main(String[] args) {
        WebDriver driver = new ChromeDriver();
        driver.get("https://gc-dev.centralindia.cloudapp.azure.com/ambica/master-data/color");
        driver.findElement(By.xpath("//button[contains(text(),'Add Color Type')]")).click();
        driver.findElement(By.id("colorName")).sendKeys("Selenium Gold");
        driver.findElement(By.xpath("//button[contains(text(),'Save')]")).click();
        driver.quit();
    }
}
